solution:
def fib_calls(n):
    memo = {}
    calls = 0

    def fib(k):
        nonlocal calls
        calls += 1
        if k in memo:
            return memo[k]
        value = k if k < 2 else fib(k - 1) + fib(k - 2)
        memo[k] = value
        return value

    return [fib(n), calls]

